<script lang="ts">
 import {motion,surfaceTransition} from './motion';
 import {untrack} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {Search,ChevronLeft,ChevronRight,Check,LoaderCircle} from 'lucide-svelte';
 import type {DocumentSession,Language} from './types';
 type Item={id:number;part:string;label:string;text:string;kind:string;editable:boolean};
 type Draft={item:Item;text:string;kind:string;style:Record<string,unknown>;revision:number};
 let {doc,lang,drafts,onchange,onbusy,onerror}:{doc:DocumentSession;lang:Language;drafts:Record<string,Draft|undefined>;onchange:(d:DocumentSession)=>void;onbusy:(v:boolean)=>void;onerror:(e:string)=>void}=$props();
 const t=(zh:string,en:string)=>lang==='zh'?zh:en;
 let labels=$state<Record<string,string>>({});
 let items=$state<Item[]>([]),parts=$state<string[]>([]),total=$state(0),offset=$state(0),query=$state(''),part=$state(''),loading=$state(false),busy=$state(false),request=0;
 const draft=$derived(drafts[doc.id]);
 let newAddress=$state('');
 const title=$derived(doc.format==='xlsx'?'Excel':doc.format==='pptx'?'PowerPoint':'Word');
 async function load(){const token=++request;const id=doc.id;loading=true;try{const result=await invoke<{items:Item[];parts:string[];total:number;labels:Record<string,string>}>('office_content',{id,offset,query,part});if(token!==request)return;items=result.items;parts=result.parts;labels=result.labels;total=result.total;}catch(e){if(token===request)onerror(String(e));}finally{if(token===request)loading=false;}}
 $effect(()=>{doc.id;doc.revision;offset;part;untrack(load);});
 function select(item:Item){if(draft&&(draft.text!==draft.item.text||Object.keys(draft.style).length>0||draft.kind!==(['number','formula'].includes(draft.item.kind)?draft.item.kind:'text'))){onerror(t('请先应用或取消当前修改。','Apply or discard the current change first.'));return;}drafts[doc.id]={item,text:item.text,kind:['number','formula'].includes(item.kind)?item.kind:'text',style:{},revision:doc.revision};}
 function addCell(){if(!part){onerror(t('请先选择一个工作表。','Select a worksheet first.'));return;}if(draft){onerror(t('请先应用或取消当前修改。','Apply or discard the current change first.'));return;}const address=newAddress.trim().toUpperCase();if(!address){onerror(t('请输入单元格地址，如 A1。','Enter a cell address, such as A1.'));return;}drafts[doc.id]={item:{id:100000,part,label:address,text:'',kind:'text',editable:true},text:'',kind:'text',style:{part,address},revision:doc.revision};}
 async function apply(){if(!draft||busy)return;const id=doc.id;busy=true;onbusy(true);try{const result=await invoke<DocumentSession>('edit_office',{id,item:draft.item.id,text:draft.text,kind:draft.kind,style:draft.style,revision:draft.revision});delete drafts[id];onchange(result);}catch(e){onerror(String(e));}finally{busy=false;onbusy(false);}}
 function page(delta:number){offset=Math.max(0,offset+delta*80);}
</script>
<aside class="office-editor" in:surfaceTransition={{kind:'panel'}} out:surfaceTransition={{kind:'panel',exit:true}} aria-label={t('Office 内容编辑','Office content editor')}>
 <div class="office-heading"><strong>{title}</strong><span>{t('兼容模式','Compatibility mode')}</span></div>
 <p class="hint">{t('修改内容后更新预览，另存保留原格式。复杂排版请核对预览。','Apply changes to refresh the preview. Save in the original format; review complex layouts.')}</p>
 {#if !doc.name.toLowerCase().endsWith('.'+doc.format)}<p class="hint">{t('旧格式已转为兼容副本，另存格式为','Legacy format converted to a compatibility copy; saves as')} .{doc.format}</p>{/if}
 {#if doc.format==='xlsx'}<p class="hint">{t('编辑文本、数值和常用公式，按地址新增单元格。复杂公式、受保护单元格只读；原公式和样式会保留，Excel 打开时重新计算。','Edit text, numbers and basic formulas; add cells by address. Complex formulas and protected cells are read-only; formulas and styles are retained and recalculated when opened in Excel.')}</p>{:else}<p class="hint">{t('按原样式文字片段编辑，保留图片和段落结构。','Edit text runs while retaining their styling, images and paragraph structure.')}</p>{/if}
 {#if parts.length>1||doc.format==='xlsx'}<label>{t(doc.format==='xlsx'?'工作表':'幻灯片','Section')}<select disabled={busy} bind:value={part} onchange={()=>offset=0}><option value="">{t('全部','All')}</option>{#each parts as name}<option value={name}>{labels[name]||name}</option>{/each}</select></label>{/if}
 {#if doc.format==='xlsx'}<form class="office-search" onsubmit={e=>{e.preventDefault();addCell();}}><input aria-label={t('新增单元格地址','New cell address')} bind:value={newAddress} placeholder={t('新增单元格，如 D12','New cell, e.g. D12')}/><button class="secondary" disabled={busy}>{t('新增','Add')}</button></form>{/if}
 <form class="office-search" onsubmit={e=>{e.preventDefault();offset=0;load();}}><input aria-label={t('查找内容或单元格','Find content or cell')} bind:value={query} placeholder={t('查找内容或单元格…','Find content or cell…')}/><button class="icon-button" title={t('查找','Find')}><Search size={16}/></button></form>
 <div class="office-items" use:motion={{key:items,kind:'item'}} aria-busy={loading}>{#if loading}<p class="hint">{t('正在读取…','Loading…')}</p>{/if}{#each items as item (item.id)}<button class:chosen={draft?.item.id===item.id} disabled={busy} onclick={()=>select(item)}><small>{parts.length>1?(labels[item.part]||item.part)+' · ':''}{item.label}{!item.editable?' · '+t('只读','Read-only'):''}</small><span>{item.text||t('（空）','(empty)')}</span></button>{:else}{#if !loading}<p class="hint">{t('没有匹配的内容','No matching content')}</p>{/if}{/each}</div>
 <div class="office-pager"><button class="icon-button" disabled={offset===0||busy||loading} onclick={()=>page(-1)} title={t('上一组','Previous items')}><ChevronLeft size={16}/></button><small>{total?offset+1:0}–{Math.min(offset+80,total)} / {total}</small><button class="icon-button" disabled={offset+80>=total||busy||loading} onclick={()=>page(1)} title={t('下一组','Next items')}><ChevronRight size={16}/></button></div>
 {#if draft}<div class="office-draft" use:motion={{key:draft.item.id,kind:'panel'}}><label>{t('内容','Content')}<textarea rows="5" readonly={!draft.item.editable||busy} value={draft.text} oninput={e=>{drafts[doc.id]={...draft,text:e.currentTarget.value};}} onkeydown={e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();if(draft.item.editable)apply();}}}></textarea></label>{#if doc.format==='xlsx'&&draft.item.editable}<label>{t('数据类型','Data type')}<select value={draft.kind} disabled={busy} onchange={e=>drafts[doc.id]={...draft,kind:e.currentTarget.value}}><option value="text">{t('文本','Text')}</option><option value="number">{t('数值','Number')}</option><option value="formula">{t('常用公式','Basic formula')}</option></select></label>{/if}{#if doc.format!=='xlsx'&&draft.item.editable}<div class="office-style">{#each [{key:'bold',zh:'粗体',en:'Bold'},{key:'italic',zh:'斜体',en:'Italic'},{key:'underline',zh:'下划线',en:'Underline'}] as f}<label>{t(f.zh,f.en)}<select disabled={busy} value={draft.style[f.key]===undefined?'keep':String(draft.style[f.key])} onchange={e=>{const style={...draft.style};if(e.currentTarget.value==='keep')delete style[f.key];else style[f.key]=e.currentTarget.value==='true';drafts[doc.id]={...draft,style};}}><option value="keep">{t('保持原样','Keep original')}</option><option value="true">{t('开启','On')}</option><option value="false">{t('关闭','Off')}</option></select></label>{/each}<label>{t('字号','Font size')}<input type="number" min="4" max="200" step="0.5" disabled={busy} placeholder={t('保持原样','Keep original')} value={draft.style.size as number ?? ''} oninput={e=>{const style={...draft.style};if(e.currentTarget.value==='')delete style.size;else style.size=Number(e.currentTarget.value);drafts[doc.id]={...draft,style};}}/></label></div>{/if}<div class="button-row"><button class="secondary" onclick={()=>{if(busy)invoke('cancel_task',{id:doc.id}).catch(e=>onerror(String(e)));else delete drafts[doc.id];}}>{busy?t('取消处理','Cancel processing'):t('取消','Cancel')}</button><button class="primary" disabled={busy||!draft.item.editable} onclick={apply}>{#if busy}<LoaderCircle size={15} class="spin"/>{:else}<Check size={15}/>{/if}{busy?t('更新预览…','Updating preview…'):t('应用修改','Apply changes')}</button></div></div>{/if}
</aside>
<style>
 .office-editor{width:320px;min-width:280px;max-width:38vw;display:flex;flex-direction:column;gap:10px;padding:16px;border-left:1px solid var(--line);background:var(--surface);overflow:auto}.office-heading{display:flex;align-items:center;justify-content:space-between}.office-heading strong{font-size:16px}.office-heading span{font-size:10px;color:var(--muted)}.hint{font-size:11px;line-height:1.6;color:var(--secondary);margin:0}.office-editor label{display:flex;flex-direction:column;gap:6px;font-size:11px}.office-search{display:flex;gap:4px}.office-search input{min-width:0;flex:1}.office-items{overflow:auto;flex:1;min-height:100px;max-height:45vh;contain:layout style}.office-items button{display:flex;flex-direction:column;text-align:left;gap:5px;width:100%;padding:10px;border-radius:6px;border-bottom:1px solid var(--line)}.office-items button:hover,.office-items button.chosen{background:var(--blue-soft)}.office-items small{font-size:10px;color:var(--muted)}.office-items span{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.office-style{display:flex;flex-wrap:wrap;gap:6px}.office-style label{flex:1;min-width:70px}.office-style input{width:100%}.office-pager{display:flex;align-items:center;justify-content:space-between}.office-draft{display:flex;flex-direction:column;gap:10px}.office-draft textarea{width:100%;resize:vertical;min-height:75px;max-height:25vh}
</style>
